INSERT INTO titles (name, title_type, release_year, phase_id, synopsis) VALUES
  ('Iron Man', 'movie', 2008, (SELECT phase_id FROM phases WHERE phase_number=1), 'Billionaire Tony Stark builds a powered suit to escape captivity and becomes Iron Man.'),
  ('The Incredible Hulk', 'movie', 2008, (SELECT phase_id FROM phases WHERE phase_number=1), 'Bruce Banner hunts for a cure while on the run from the military.'),
  ('Iron Man 2', 'movie', 2010, (SELECT phase_id FROM phases WHERE phase_number=1), 'Tony Stark faces the world''s demand for his tech and a vengeful Russian rival.'),
  ('Thor', 'movie', 2011, (SELECT phase_id FROM phases WHERE phase_number=1), 'The arrogant god Thor is banished to Earth and must prove himself worthy.'),
  ('Captain America: The First Avenger', 'movie', 2011, (SELECT phase_id FROM phases WHERE phase_number=1), 'Steve Rogers becomes a super-soldier and fights HYDRA in World War II.'),
  ('The Avengers', 'movie', 2012, (SELECT phase_id FROM phases WHERE phase_number=1), 'Earth''s mightiest heroes unite to stop Loki and an alien invasion.'),
  ('Iron Man 3', 'movie', 2013, (SELECT phase_id FROM phases WHERE phase_number=2), 'Tony Stark battles the Mandarin while struggling with anxiety after New York.'),
  ('Thor: The Dark World', 'movie', 2013, (SELECT phase_id FROM phases WHERE phase_number=2), 'Thor must stop the Dark Elves from plunging the universe into darkness.'),
  ('Captain America: The Winter Soldier', 'movie', 2014, (SELECT phase_id FROM phases WHERE phase_number=2), 'Steve Rogers uncovers a conspiracy inside S.H.I.E.L.D.'),
  ('Guardians of the Galaxy', 'movie', 2014, (SELECT phase_id FROM phases WHERE phase_number=2), 'A band of misfits steals an orb and ends up saving the galaxy.'),
  ('Avengers: Age of Ultron', 'movie', 2015, (SELECT phase_id FROM phases WHERE phase_number=2), 'The Avengers face Ultron, an AI bent on wiping out humanity.'),
  ('Ant-Man', 'movie', 2015, (SELECT phase_id FROM phases WHERE phase_number=2), 'Thief Scott Lang inherits a suit that shrinks him and pulls off a heist.'),
  ('Captain America: Civil War', 'movie', 2016, (SELECT phase_id FROM phases WHERE phase_number=3), 'The Avengers split over government oversight and fight each other.'),
  ('Doctor Strange', 'movie', 2016, (SELECT phase_id FROM phases WHERE phase_number=3), 'A brilliant surgeon learns the mystic arts after a career-ending accident.'),
  ('Guardians of the Galaxy Vol. 2', 'movie', 2017, (SELECT phase_id FROM phases WHERE phase_number=3), 'The Guardians meet Peter Quill''s father and fight to keep their family together.'),
  ('Spider-Man: Homecoming', 'movie', 2017, (SELECT phase_id FROM phases WHERE phase_number=3), 'Peter Parker balances high school life with being a hero under Tony Stark''s watch.'),
  ('Thor: Ragnarok', 'movie', 2017, (SELECT phase_id FROM phases WHERE phase_number=3), 'Thor must escape the planet Sakaar to save Asgard from Hela.'),
  ('Black Panther', 'movie', 2018, (SELECT phase_id FROM phases WHERE phase_number=3), 'T''Challa returns to Wakanda to take the throne and face Killmonger.'),
  ('Avengers: Infinity War', 'movie', 2018, (SELECT phase_id FROM phases WHERE phase_number=3), 'The Avengers and Guardians fight Thanos for the Infinity Stones.'),
  ('Ant-Man and the Wasp', 'movie', 2018, (SELECT phase_id FROM phases WHERE phase_number=3), 'Scott Lang and Hope van Dyne race to rescue Janet from the Quantum Realm.'),
  ('Captain Marvel', 'movie', 2019, (SELECT phase_id FROM phases WHERE phase_number=3), 'Carol Danvers becomes one of the universe''s most powerful heroes.'),
  ('Avengers: Endgame', 'movie', 2019, (SELECT phase_id FROM phases WHERE phase_number=3), 'The surviving Avengers attempt to undo Thanos''s snap.'),
  ('Spider-Man: Far From Home', 'movie', 2019, (SELECT phase_id FROM phases WHERE phase_number=3), 'Peter Parker''s European trip is interrupted by Nick Fury and Mysterio.'),
  ('Black Widow', 'movie', 2021, (SELECT phase_id FROM phases WHERE phase_number=4), 'Natasha Romanoff confronts the dark side of her past.'),
  ('Shang-Chi and the Legend of the Ten Rings', 'movie', 2021, (SELECT phase_id FROM phases WHERE phase_number=4), 'Shang-Chi is drawn into the Ten Rings organization he tried to leave behind.'),
  ('Eternals', 'movie', 2021, (SELECT phase_id FROM phases WHERE phase_number=4), 'Immortal beings reunite to protect humanity from the Deviants.'),
  ('Spider-Man: No Way Home', 'movie', 2021, (SELECT phase_id FROM phases WHERE phase_number=4), 'A spell gone wrong brings villains from other universes to Peter''s world.'),
  ('Doctor Strange in the Multiverse of Madness', 'movie', 2022, (SELECT phase_id FROM phases WHERE phase_number=4), 'Doctor Strange crosses the multiverse to protect America Chavez.'),
  ('Thor: Love and Thunder', 'movie', 2022, (SELECT phase_id FROM phases WHERE phase_number=4), 'Thor teams up with Jane Foster to stop Gorr the God Butcher.'),
  ('Black Panther: Wakanda Forever', 'movie', 2022, (SELECT phase_id FROM phases WHERE phase_number=4), 'Wakanda defends itself from Talokan after the loss of King T''Challa.'),
  ('Ant-Man and the Wasp: Quantumania', 'movie', 2023, (SELECT phase_id FROM phases WHERE phase_number=5), 'Scott, Hope and their family get trapped in the Quantum Realm with Kang.'),
  ('Guardians of the Galaxy Vol. 3', 'movie', 2023, (SELECT phase_id FROM phases WHERE phase_number=5), 'The Guardians fight to save Rocket''s life and past.'),
  ('The Marvels', 'movie', 2023, (SELECT phase_id FROM phases WHERE phase_number=5), 'Carol Danvers, Monica Rambeau and Kamala Khan swap places when their powers entangle.'),
  ('Deadpool & Wolverine', 'movie', 2024, (SELECT phase_id FROM phases WHERE phase_number=5), 'Deadpool recruits a reluctant Wolverine to save his universe.'),
  ('Captain America: Brave New World', 'movie', 2025, (SELECT phase_id FROM phases WHERE phase_number=5), 'Sam Wilson steps in as Captain America amid an international crisis.'),
  ('Thunderbolts*', 'movie', 2025, (SELECT phase_id FROM phases WHERE phase_number=5), 'A team of antiheroes is pulled into a deadly trap set by the government.'),
  ('The Fantastic Four: First Steps', 'movie', 2025, (SELECT phase_id FROM phases WHERE phase_number=6), 'Marvel''s first family protects a retro-futuristic Earth from Galactus.'),
  ('WandaVision', 'series', 2021, (SELECT phase_id FROM phases WHERE phase_number=4), 'Wanda and Vision live in a sitcom-style suburb that hides a strange truth.'),
  ('The Falcon and the Winter Soldier', 'series', 2021, (SELECT phase_id FROM phases WHERE phase_number=4), 'Sam Wilson and Bucky Barnes team up to deal with the legacy of the shield.'),
  ('Loki', 'series', 2021, (SELECT phase_id FROM phases WHERE phase_number=4), 'After stealing the Tesseract, Loki is dragged into the Time Variance Authority.'),
  ('What If...?', 'series', 2021, (SELECT phase_id FROM phases WHERE phase_number=4), 'An animated anthology that rewrites key moments of the MCU.'),
  ('Hawkeye', 'series', 2021, (SELECT phase_id FROM phases WHERE phase_number=4), 'Clint Barton teams up with Kate Bishop over the Christmas season.'),
  ('Moon Knight', 'series', 2022, (SELECT phase_id FROM phases WHERE phase_number=4), 'Steven Grant discovers he shares a body with a mercenary and an Egyptian god''s avatar.'),
  ('Ms. Marvel', 'series', 2022, (SELECT phase_id FROM phases WHERE phase_number=4), 'Teen Kamala Khan gains powers and becomes her hero, Ms. Marvel.'),
  ('She-Hulk: Attorney at Law', 'series', 2022, (SELECT phase_id FROM phases WHERE phase_number=4), 'Jennifer Walters balances a law career with being a Hulk.'),
  ('Secret Invasion', 'series', 2023, (SELECT phase_id FROM phases WHERE phase_number=5), 'Nick Fury uncovers a Skrull infiltration of Earth.'),
  ('Agatha All Along', 'series', 2024, (SELECT phase_id FROM phases WHERE phase_number=5), 'Agatha Harkness walks the Witches'' Road to regain her powers.'),
  ('Ironheart', 'series', 2025, (SELECT phase_id FROM phases WHERE phase_number=5), 'Riri Williams builds her own suit and faces a dangerous rival in Chicago.'),
